    #[test]
    fn an_order_refused_for_command_power_waits_until_the_power_read_reaches_the_cost() {
        let refusal = "Promoting Fedor von Bock to field marshal costs 40 command power and 2 are \
                       held; nothing was changed";
        let short = fake(vec![(
            "hoi4_country_status",
            json!({"fields": {"command_power": {"value": 31.5}}}),
        )]);
        short.refuse_with("hoi4_army_commander", "insufficient_command_power", refusal);
        let mut state = State {
            clock: START,
            ..State::default()
        };
        let args = json!({"army": "Army Group 1", "general": "Fedor von Bock"});
        let sent = |t: &Fake| {
            t.calls
                .borrow()
                .iter()
                .filter(|(n, a)| n == "hoi4_army_commander" && a.get("request_id").is_some())
                .count()
        };
        let (ok, _) = state
            .act(&short, "l", "hoi4_army_commander", args.clone(), "af")
            .unwrap();
        assert!(!ok);
        assert_eq!(sent(&short), 1);
        // later, still short: not sent, and the refusal carries the power read now
        state.clock = START + 30 * DAY;
        let (ok, why) = state
            .act(&short, "l", "hoi4_army_commander", args.clone(), "af")
            .unwrap();
        assert!(!ok);
        assert_eq!(sent(&short), 1, "{why}");
        assert!(
            why.contains("costs 40 command power and 31.5 are held"),
            "{why}"
        );
        assert_eq!(plan_military::cp_wait_days(&why), 22);
        // enough command power now: the order goes out
        let enough = fake(vec![(
            "hoi4_country_status",
            json!({"fields": {"command_power": {"value": 41.0}}}),
        )]);
        state.clock = START + 60 * DAY;
        let (ok, _) = state
            .act(&enough, "l", "hoi4_army_commander", args, "af")
            .unwrap();
        assert!(ok);
        assert_eq!(sent(&enough), 1);
    }

    struct Fake {
        calls: RefCell<Vec<(String, Value)>>,
        replies: HashMap<&'static str, Value>,
        refuse: RefCell<HashMap<String, &'static str>>,
        refuse_text: RefCell<HashMap<String, String>>,
    }
    impl Fake {
        fn refuse_with(&self, what: &str, code: &'static str, text: &str) {
            self.refuse.borrow_mut().insert(what.into(), code);
            self.refuse_text
                .borrow_mut()
                .insert(what.into(), text.into());
        }
        fn refuse(&self, what: &str, code: &'static str) {
            self.refuse.borrow_mut().insert(what.into(), code);
        }
    }
    impl Tools for Fake {
        fn call(&self, name: &str, args: &Value) -> Result<Value> {
            self.calls
                .borrow_mut()
                .push((name.to_string(), args.clone()));
            if name.starts_with("hoi4_") && args.get("request_id").is_some() {
                if let Some(code) = self.refuse.borrow().get(name) {
                    let text = self.refuse_text.borrow().get(name).cloned();
                    return Err(crate::error::Error::new(
                        code,
                        text.unwrap_or_else(|| "refused by the fake".into()),
                    ));
                }
                return Ok(json!({"receipt": {"status": "Verified"}}));
            }
            Ok(self.replies.get(name).cloned().unwrap_or_else(|| json!({})))
        }
    }
    fn fake(replies: Vec<(&'static str, Value)>) -> Fake {
        Fake {
            calls: RefCell::new(Vec::new()),
            replies: replies.into_iter().collect(),
            refuse: RefCell::new(HashMap::new()),
            refuse_text: RefCell::new(HashMap::new()),
        }
    }
