    #[test]
    fn a_short_queue_is_filled_even_with_every_factory_busy() {
        // Ethiopia run 10: one project took all 12 factories; when it finished the runner
        // queued the next one only on a later tick. A queue deeper than the pool avoids that.
        struct Busy(Builder, i64);
        impl Tools for Busy {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                if name == "hoi4_economy" {
                    return Ok(json!({"factory_trigger_count": {"military": 0},
                        "civilian_factories_available_for_projects": 12, "civilian_factories_idle": 0,
                        "construction_projects_queued": self.1, "player": "ITA"}));
                }
                self.0.call(name, args)
            }
        }
        let mut b = Builder::new();
        b.slots = [(4, 5)].into();
        let plan = json!({"construction": [{"building": "industrial_complex", "states": [4]}]});
        let short = Busy(b, 1);
        let mut state = State::default();
        let step = acted(tick(&mut state, &short, &plan, "l", START).unwrap());
        assert!(
            step.starts_with("construct industrial_complex 4: true"),
            "{step}"
        );
        assert_eq!(*short.0.added.borrow(), vec![(4, 1)]);
        let mut b = Builder::new();
        b.slots = [(4, 5)].into();
        let full = Busy(b, 3);
        let mut state = State::default();
        assert_eq!(
            tick(&mut state, &full, &plan, "l", START).unwrap(),
            Tick::Nothing
        );
        assert!(state.con.digest.clone().unwrap().contains("queue is full"));
    }

    #[test]
    fn the_queue_grows_with_the_factory_pool() {
        // g17g2: 117 civilian factories behind a three-project queue left 49-65 of them idle
        struct Big(Builder, i64);
        impl Tools for Big {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                if name == "hoi4_economy" {
                    return Ok(json!({"factory_trigger_count": {"military": 0},
                        "civilian_factories_available_for_projects": 117, "civilian_factories_idle": 0,
                        "construction_projects_queued": self.1, "player": "GER"}));
                }
                self.0.call(name, args)
            }
        }
        let plan = json!({"construction": [{"building": "arms_factory", "states": [4]}]});
        let mut b = Builder::new();
        b.slots = [(4, 5)].into();
        let three = Big(b, 3);
        let mut state = State::default();
        let step = acted(tick(&mut state, &three, &plan, "l", START).unwrap());
        assert!(step.starts_with("construct arms_factory 4: true"), "{step}");
        // 117 factories: 8 projects of 15 and one more
        let mut b = Builder::new();
        b.slots = [(4, 5)].into();
        let nine = Big(b, 9);
        let mut state = State::default();
        assert_eq!(
            tick(&mut state, &nine, &plan, "l", START).unwrap(),
            Tick::Nothing
        );
    }

    #[test]
    fn a_failing_slot_read_is_not_fatal_and_a_blocked_add_pauses_every_state() {
        let mut b = Builder::new();
        b.probe_fails = true;
        let plan = json!({"construction": [{"building": "arms_factory", "states": [4, 5]}]});
        let mut state = State::default();
        let step = acted(tick(&mut state, &b, &plan, "l", START).unwrap());
        assert!(step.starts_with("construct arms_factory 4: true"), "{step}");
        assert!(state
            .con
            .digest
            .clone()
            .unwrap()
            .contains("probe:ui_blocked"));
        // an event or pop-up refusing input is not the state's fault
        struct Blocked;
        impl Tools for Blocked {
            fn call(&self, name: &str, _: &Value) -> Result<Value> {
                match name {
                    "hoi4_research" => Ok(json!({"slots": [{"researching": "a"}]})),
                    "hoi4_focus_completed" => Ok(json!({"active_key": "f"})),
                    "hoi4_economy" => Ok(json!({"civilian_factories_available_for_projects": 9})),
                    "hoi4_construction_add" => Err(Error::new("ui_blocked", "event open")),
                    _ => Ok(json!({})),
                }
            }
        }
        let plan = json!({"construction": [{"building": "arms_factory", "states": [4, 5]}], "construction_probe_slots": false});
        let mut state = State::default();
        acted(tick(&mut state, &Blocked, &plan, "l", START).unwrap());
        assert_eq!(
            tick(&mut state, &Blocked, &plan, "l", START + 2).unwrap(),
            Tick::Nothing
        );
        assert!(state.con.digest.clone().unwrap().contains("paused"));
        // no state was marked failed or full: after the pause both are tried again
        assert!(!state.skipped(START + 7, "confull", "slots:4"));
        assert!(matches!(
            tick(&mut state, &Blocked, &plan, "l", START + 7).unwrap(),
            Tick::Acted(_)
        ));
    }

    #[test]
    fn construction_runs_before_armies_that_always_have_something_to_retry() {
        struct Both(Builder);
        impl Tools for Both {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                if name == "hoi4_armies" {
                    return Ok(
                        json!({"unassigned_by_state": [{"state_id": 56, "divisions": 4}], "armies": []}),
                    );
                }
                if name == "hoi4_army_create" {
                    return Ok(json!({"receipt": {"status": "Verified"}}));
                }
                self.0.call(name, args)
            }
        }
        let mut inner = Builder::new();
        inner.slots = [(4, 5)].into();
        let tools = Both(inner);
        let plan = json!({"construction": [{"building": "arms_factory", "states": [4]}], "armies": {"max": 24}});
        let mut state = State::default();
        let first = acted(tick(&mut state, &tools, &plan, "l", START).unwrap());
        assert!(first.starts_with("construct arms_factory 4"), "{first}");
        let second = acted(tick(&mut state, &tools, &plan, "l", START + 1).unwrap());
        assert!(second.starts_with("army_create state 56"), "{second}");
    }

    #[test]
    fn a_stalled_construction_raises_an_alarm_after_the_configured_days() {
        let b = Builder::new();
        let mut state = State {
            last_hour: START + 6 * DAY,
            ..State::default()
        };
        state.con.baseline = Some(START);
        let plan = json!({"construction": [{"building": "arms_factory", "states": [4]}]});
        let alarm =
            construction_alarm(&state, &b, &plan, Some("construction: idle=20 [4:full]")).unwrap();
        assert_eq!(alarm["code"], json!("construction_stalled"));
        assert!(alarm["message"].as_str().unwrap().contains("4:full"));
        state.con.last_queue = Some(START + 5 * DAY);
        assert!(construction_alarm(&state, &b, &plan, None).is_none());
        let off = json!({"construction": [{"building": "x", "states": [1]}], "alarms": {"construction_stalled": false}});
        state.con.last_queue = None;
        assert!(construction_alarm(&state, &b, &off, None).is_none());
    }

    #[test]
    fn unassigned_divisions_get_an_army_and_big_armies_are_split() {
        struct Roster;
        impl Tools for Roster {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                match name {
                    "hoi4_research" => Ok(json!({"slots": [{"researching": "a"}]})),
                    "hoi4_focus_completed" => Ok(json!({"active_key": "f"})),
                    "hoi4_economy" => Ok(json!({"factory_trigger_count": {"military": 0},
                        "civilian_factories_available_for_projects": 0})),
                    "hoi4_armies" => Ok(json!({
                        "unassigned_by_state": [{"state_id": 66, "divisions": 3}],
                        "armies": [{"army": "Army 1", "division_count": 40, "commander": null}]})),
                    "hoi4_army_create" => {
                        if args.get("absorb_existing").is_some() {
                            Ok(json!({"receipt": {"status": "Verified"}}))
                        } else {
                            Err(Error::new(
                                "invalid_target",
                                "Divisions of an existing army stand here",
                            ))
                        }
                    }
                    "hoi4_army_assign" => {
                        Err(Error::new("capability_unavailable", "control not mapped"))
                    }
                    "hoi4_army_split" => {
                        assert_eq!(args["count"], json!(16));
                        Ok(json!({"receipt": {"status": "Verified"}}))
                    }
                    _ => Ok(json!({})),
                }
            }
        }
        let plan = json!({"armies": {"max": 24, "absorb": true}});
        let mut state = State::default();
        let now = START;
        // the assign control is unmapped: the older create/merge path still works
        let first = tick(&mut state, &Roster, &plan, "l", now).unwrap();
        assert!(matches!(&first, Tick::Acted(s) if s.starts_with("army_create state 66: true")));
        // the state is retried later; the oversized army is split next
        state.skip(now, "armycreate", "66", 2 * DAY);
        let second = tick(&mut state, &Roster, &plan, "l", now).unwrap();
        assert!(matches!(&second, Tick::Acted(s) if s.starts_with("army_split Army 1 16: true")));
    }

    #[test]
    fn fresh_divisions_of_a_training_row_join_its_army_with_the_most_room_by_command() {
        struct Fresh(RefCell<Vec<(String, Value)>>, bool);
        impl Tools for Fresh {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                self.0.borrow_mut().push((name.to_string(), args.clone()));
                match name {
                    "hoi4_supply" => Ok(json!({"divisions": [
                        {"id": "d1", "template": "Infanterie-Division"},
                        {"id": "d2", "template": "Infanterie-Division"},
                        {"id": "d3", "template": "Panzer-Division"}]})),
                    "hoi4_army_detach" if self.1 => Ok(json!({"receipt": {"status": "Verified"}})),
                    "hoi4_army_detach" => Err(Error::new("capability_unavailable", "units off")),
                    _ => Ok(json!({})),
                }
            }
        }
        let roster = json!({"unassigned": ["d1", "d2", "d3"], "armies": [
            {"army": "Armee 1", "division_count": 20},
            {"army": "Armee 2", "division_count": 12},
            {"army": "Armee 3", "division_count": 2}]});
        let plan = json!({"training": [
            {"template": "Infanterie-Division", "queue": 6, "armies": ["Armee 1", "Armee 2"]},
            {"template": "Panzer-Division", "queue": 2}]});
        let tools = Fresh(RefCell::new(vec![]), true);
        let mut state = State::default();
        let line = route_trainees(&mut state, &tools, &plan, &roster, 24, "l", START)
            .unwrap()
            .unwrap();
        assert!(
            line.starts_with("trainees 2 Infanterie-Division -> Armee 2: true"),
            "{line}"
        );
        let sent = tools.0.borrow();
        let detach = sent.iter().find(|(n, _)| n == "hoi4_army_detach").unwrap();
        assert_eq!(detach.1["divisions"], json!(["d1", "d2"]));
        assert_eq!(detach.1["into"], json!("Armee 2"));
        assert!(detach.1.get("army").is_none());
        drop(sent);
        // a refusal waits 7 days; the gather takes them meanwhile
        let off = Fresh(RefCell::new(vec![]), false);
        let mut state = State::default();
        route_trainees(&mut state, &off, &plan, &roster, 24, "l", START).unwrap();
        assert!(
            route_trainees(&mut state, &off, &plan, &roster, 24, "l", START + DAY)
                .unwrap()
                .is_none()
        );
        // no row with armies: nothing
        let plain = json!({"training": {"template": "Infanterie-Division"}});
        assert!(route_trainees(
            &mut State::default(),
            &tools,
            &plain,
            &roster,
            24,
            "l",
            START
        )
        .unwrap()
        .is_none());
    }

    #[test]
    fn unassigned_divisions_are_gathered_in_one_action_not_state_by_state() {
        struct Gathering(RefCell<Vec<(String, Value)>>, bool);
        impl Tools for Gathering {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                self.0.borrow_mut().push((name.to_string(), args.clone()));
                match name {
                    "hoi4_research" => Ok(json!({"slots": [{"researching": "a"}]})),
                    "hoi4_focus_completed" => Ok(json!({"active_key": "f"})),
                    "hoi4_economy" => Ok(json!({"civilian_factories_available_for_projects": 0})),
                    "hoi4_armies" => Ok(json!({
                        "unassigned": ["d1", "d2", "d3"],
                        "unassigned_by_state": [{"state_id": 56, "divisions": 2}, {"state_id": 57, "divisions": 1}],
                        "armies": [
                            {"army": "Army 1", "division_count": 10, "battle_plan_orders": 0},
                            {"army": "Army 2", "division_count": 22, "battle_plan_orders": 0},
                            {"army": "Army 3", "division_count": 15, "battle_plan_orders": 4}]})),
                    "hoi4_alerts" => Ok(json!({"alerts": [{"alert": "unassigned_divisions"}]})),
                    "hoi4_army_gather" if self.1 => Ok(json!({"receipt": {"status": "Verified"}})),
                    "hoi4_army_gather" => Err(Error::new("unknown_tool", "Unknown tool")),
                    "hoi4_army_assign" => Ok(json!({"receipt": {"status": "Verified"}})),
                    _ => Ok(json!({})),
                }
            }
        }
        let plan = json!({"armies": {"max": 24, "absorb": "assign"}});
        let tools = Gathering(RefCell::new(vec![]), true);
        let step = acted(tick(&mut State::default(), &tools, &plan, "l", START).unwrap());
        // the fullest army without battle-plan orders that still has room: Army 2 (22+3 > 24) no
        assert!(step.starts_with("army_gather 3 -> Army 1: true"), "{step}");
        let sent = tools.0.borrow();
        let gather = sent.iter().find(|(n, _)| n == "hoi4_army_gather").unwrap();
        assert_eq!(gather.1["army"], json!("Army 1"));
        assert!(!sent.iter().any(|(n, _)| n == "hoi4_army_assign"));
        drop(sent);
        // the plan names the army: it is used when it has room
        let plan = json!({"armies": {"max": 24, "gather_into": "Army 3"}});
        let tools = Gathering(RefCell::new(vec![]), true);
        let step = acted(tick(&mut State::default(), &tools, &plan, "l", START).unwrap());
        assert!(step.starts_with("army_gather 3 -> Army 3: true"), "{step}");
        // an army an operation owns is no target: the next with room is
        let mut state = State::default();
        state.op_owned.insert("Army 3".into(), "op_x".into());
        let roster = Gathering(RefCell::new(vec![]), true)
            .call("hoi4_armies", &json!({}))
            .unwrap();
        assert_eq!(
            gather_target(&state, &plan, &roster, 3, 24).as_deref(),
            Some("Army 1")
        );
        // an older backend without the tool: the state-by-state path is the fallback
        let plan = json!({"armies": {"max": 24, "absorb": "assign"}});
        let tools = Gathering(RefCell::new(vec![]), false);
        let step = acted(tick(&mut State::default(), &tools, &plan, "l", START).unwrap());
        assert!(step.starts_with("army_assign state 56: true"), "{step}");
    }

    fn manage_note(state: &State, key: &str) -> String {
        plan_manage::digest(state)
            .and_then(|d| d[key].as_str().map(String::from))
            .unwrap_or_default()
    }

    /// g17a (17 Nov 2026): 13 gathers refused "alert is not shown", 12 assigns refused
    /// (army_full, selection_unavailable, selection_mismatch) for fresh divisions.
    struct FreshDivisions {
        sent: RefCell<Vec<(String, Value)>>,
        alert: bool,
        full: bool,
        refusal: Option<&'static str>,
    }
    impl Tools for FreshDivisions {
        fn call(&self, name: &str, args: &Value) -> Result<Value> {
            if args.get("request_id").is_some() {
                self.sent
                    .borrow_mut()
                    .push((name.to_string(), args.clone()));
            }
            match name {
                "hoi4_research" => Ok(json!({"slots": [{"researching": "a"}]})),
                "hoi4_focus_completed" => Ok(json!({"active_key": "f"})),
                "hoi4_economy" => Ok(json!({"civilian_factories_available_for_projects": 0})),
                "hoi4_alerts" if self.alert => {
                    Ok(json!({"alerts": [{"alert": "unassigned_divisions"}]}))
                }
                "hoi4_alerts" => Ok(json!({"alerts": [{"alert": "decisions_available"}]})),
                "hoi4_armies" => Ok(json!({
                    "unassigned": ["d1"],
                    "unassigned_by_state": [{"state_id": 67, "divisions": 1,
                        "shared_with": {"Armee Mitte": 1}}],
                    "armies": [{"army": "Armee Mitte", "battle_plan_orders": 0,
                        "division_count": if self.full { 24 } else { 18 },
                        "states": {"67": 3}},
                        {"army": "Armee West", "battle_plan_orders": 0,
                        "division_count": 10, "states": {"5": 10}}]})),
                "hoi4_army_assign" => match self.refusal {
                    Some(code) => Err(Error::new(code, "refused")),
                    None => Ok(json!({"receipt": {"status": "Verified"}})),
                },
                "hoi4_army_gather" => Ok(json!({"receipt": {"status": "Verified"}})),
                _ => Ok(json!({})),
            }
        }
    }
    fn fresh(alert: bool, full: bool, refusal: Option<&'static str>) -> FreshDivisions {
        FreshDivisions {
            sent: RefCell::new(vec![]),
            alert,
            full,
            refusal,
        }
    }

    #[test]
    fn fresh_divisions_wait_for_the_games_alert_before_any_gather_or_assign() {
        let plan = json!({"armies": {"max": 24, "absorb": "assign"}});
        let tools = fresh(false, false, None);
        let mut state = State::default();
        assert_eq!(
            armies_step(&mut state, &tools, &plan, "l", START).unwrap(),
            None
        );
        assert!(tools.sent.borrow().is_empty());
        assert!(manage_note(&state, "armies")
            .contains("wait for the game's unassigned-divisions alert"));
        // the alert shows: one gather takes them
        let tools = fresh(true, false, None);
        let step = armies_step(&mut state, &tools, &plan, "l", START + DAY)
            .unwrap()
            .unwrap();
        assert!(
            step.starts_with("army_gather 1 -> Armee Mitte: true"),
            "{step}"
        );
        // no alert for a week: the state-by-state assign is the fallback
        let tools = fresh(false, false, None);
        let mut state = State::default();
        armies_step(&mut state, &tools, &plan, "l", START).unwrap();
        let step = armies_step(&mut state, &tools, &plan, "l", START + 7 * DAY)
            .unwrap()
            .unwrap();
        assert!(step.starts_with("army_assign state 67: true"), "{step}");
    }

    #[test]
    fn an_assign_that_cannot_apply_is_not_sent_and_a_refused_one_rests() {
        let plan = json!({"armies": {"max": 24, "absorb": "assign", "gather": false}});
        // every army standing in the state is at the cap: army_full is known before any click
        let tools = fresh(false, true, None);
        let mut state = State::default();
        assert_eq!(
            armies_step(&mut state, &tools, &plan, "l", START).unwrap(),
            None
        );
        assert!(tools.sent.borrow().is_empty());
        assert!(manage_note(&state, "armies")
            .contains("every army standing there is full (Armee Mitte 24"));
        // a division no click can take alone: refused once, then left to the gather
        let tools = fresh(false, false, Some("selection_unavailable"));
        let mut state = State::default();
        let step = armies_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(step.contains("false selection_unavailable"), "{step}");
        assert_eq!(
            armies_step(&mut state, &tools, &plan, "l", START + 10 * DAY).unwrap(),
            None
        );
        assert_eq!(tools.sent.borrow().len(), 1);
        assert!(manage_note(&state, "armies").contains("assign refused"));
    }

    #[test]
    fn a_gather_goes_to_the_formation_of_the_divisions_region_before_any_other_army() {
        // g17b (17 Nov 2026): fresh divisions in Pomerania (63) went to the western formations
        // and then into Army 1, a stray group, while Armee Nord covered Pomerania with two
        let plan = json!({"armies": {"max": 24, "gather_into": "West"},
            "army_layout": [
                {"name_hint": "Nord", "state": 5, "covers": [5, 63]},
                {"name_hint": "West", "state": 56}]});
        let roster = |nord: u64, west: u64| {
            json!({"unassigned": ["x", "y"],
                "unassigned_by_state": [{"state_id": 63, "divisions": 2}],
                "armies": [
                    {"army": "Armee Nord", "division_count": nord, "battle_plan_orders": 0},
                    {"army": "Armee West", "division_count": west, "battle_plan_orders": 0},
                    {"army": "Army 1", "division_count": 20, "battle_plan_orders": 0}]})
        };
        let mut state = State::default();
        state.layout.insert("Nord".into(), "Armee Nord".into());
        state.layout.insert("West".into(), "Armee West".into());
        let to = |nord, west| gather_target(&state, &plan, &roster(nord, west), 2, 24);
        assert_eq!(to(2, 10).as_deref(), Some("Armee Nord"));
        // the region's formation is full: the plan's gather_into
        assert_eq!(to(23, 10).as_deref(), Some("Armee West"));
        // both formations full: the fullest army with room
        assert_eq!(to(23, 23).as_deref(), Some("Army 1"));
        // nothing has room: a new army
        let full = json!({"unassigned": ["x"], "armies": [
            {"army": "Armee Nord", "division_count": 24}]});
        assert_eq!(gather_target(&state, &plan, &full, 1, 24), None);
    }

    #[test]
    fn a_loose_stack_shared_with_two_armies_is_never_assigned_and_its_rest_outlives_the_alert() {
        // g17b (17 Nov 2026): army_assign for state 63 refused selection_unavailable four
        // times; the unassigned-divisions alert cleared the 20-day rest each time
        struct Shared(RefCell<Vec<String>>, &'static str);
        impl Tools for Shared {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                if args.get("request_id").is_some() {
                    self.0.borrow_mut().push(name.to_string());
                }
                match name {
                    "hoi4_armies" if self.1 == "two" => Ok(json!({
                        "unassigned": ["d1"],
                        "unassigned_by_state": [{"state_id": 63, "divisions": 1,
                            "division_ids": ["d1"],
                            "shared_with": {"Armee West Nord": 1, "Army 1": 1}}],
                        "armies": [
                            {"army": "Armee West Nord", "division_count": 23, "states": {"63": 23}},
                            {"army": "Army 1", "division_count": 15, "states": {"63": 15}}]})),
                    "hoi4_armies" => Ok(json!({
                        "unassigned": ["d1"],
                        "unassigned_by_state": [{"state_id": 63, "divisions": 1,
                            "division_ids": ["d1"], "shared_with": {"Army 1": 1}}],
                        "armies": [{"army": "Army 1", "division_count": 15, "states": {"63": 15}}]})),
                    "hoi4_army_assign" => Err(Error::new("selection_unavailable", "refused")),
                    _ => Ok(json!({})),
                }
            }
        }
        let plan = json!({"armies": {"max": 24, "absorb": "assign", "gather": false}});
        let tools = Shared(RefCell::new(vec![]), "two");
        let mut state = State::default();
        assert_eq!(
            armies_step(&mut state, &tools, &plan, "l", START).unwrap(),
            None
        );
        assert!(tools.0.borrow().is_empty());
        let note = manage_note(&state, "armies");
        assert!(
            note.contains("no assign for d1") && note.contains("Armee West Nord, Army 1"),
            "{note}"
        );
        // one army shares it: the assign goes out once; refused, it rests 20 days even when
        // the alert nudges the armies step (its `armycreate` timers cleared)
        let tools = Shared(RefCell::new(vec![]), "one");
        let mut state = State::default();
        armies_step(&mut state, &tools, &plan, "l", START).unwrap();
        assert_eq!(tools.0.borrow().len(), 1);
        state.bad.retain(|k, _| !k.starts_with("armycreate:"));
        assert_eq!(
            armies_step(&mut state, &tools, &plan, "l", START + 3 * DAY).unwrap(),
            None
        );
        assert_eq!(tools.0.borrow().len(), 1);
    }

    #[test]
    fn unassigned_divisions_are_assigned_to_the_standing_army_before_any_merge() {
        struct Assigning(RefCell<Vec<String>>, bool);
        impl Tools for Assigning {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                self.0.borrow_mut().push(name.to_string());
                match name {
                    "hoi4_research" => Ok(json!({"slots": [{"researching": "a"}]})),
                    "hoi4_focus_completed" => Ok(json!({"active_key": "f"})),
                    "hoi4_economy" => Ok(json!({"civilian_factories_available_for_projects": 0})),
                    "hoi4_armies" => Ok(json!({
                        "unassigned_by_state": [{"state_id": 56, "divisions": 4}], "armies": []})),
                    "hoi4_army_assign" if self.1 => {
                        assert_eq!(args["state_id"], json!(56));
                        Ok(json!({"receipt": {"status": "Verified"}}))
                    }
                    "hoi4_army_assign" => {
                        Err(Error::new("capability_unavailable", "control not mapped"))
                    }
                    _ => Ok(json!({})),
                }
            }
        }
        let plan = json!({"armies": {"absorb": true}});
        let tools = Assigning(RefCell::new(vec![]), true);
        let step = acted(tick(&mut State::default(), &tools, &plan, "l", START).unwrap());
        assert!(step.starts_with("army_assign state 56: true"), "{step}");
        assert!(!tools.0.borrow().contains(&"hoi4_army_create".to_string()));
        // "assign" never merges: an unmapped control just waits and reports
        let plan = json!({"armies": {"absorb": "assign"}});
        let tools = Assigning(RefCell::new(vec![]), false);
        let mut state = State::default();
        let step = acted(tick(&mut state, &tools, &plan, "l", START).unwrap());
        assert!(
            step.starts_with("army_assign state 56: false capability_unavailable"),
            "{step}"
        );
        assert!(!tools.0.borrow().contains(&"hoi4_army_create".to_string()));
        assert!(state.skipped(START + DAY, "armycreate", "56"));
    }

    #[test]
    fn every_army_gets_a_general_from_the_plan_list_first() {
        struct Roster;
        impl Tools for Roster {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                match name {
                    "hoi4_research" => Ok(json!({"slots": [{"researching": "a"}]})),
                    "hoi4_focus_completed" => Ok(json!({"active_key": "f"})),
                    "hoi4_economy" => Ok(json!({"factory_trigger_count": {"military": 0},
                        "civilian_factories_available_for_projects": 0})),
                    "hoi4_armies" => Ok(json!({"unassigned_by_state": [], "armies": [
                        {"army": "Army 2", "division_count": 3, "commander": null},
                        {"army": "Army 3", "division_count": 12, "commander": null}]})),
                    "hoi4_army_commander" => {
                        assert_eq!(args["army"], json!("Army 2"));
                        assert_eq!(args["general"], json!("B"));
                        Ok(json!({"receipt": {"status": "Verified"}}))
                    }
                    _ => Ok(json!({})),
                }
            }
        }
        let plan = json!({"armies": {"generals": ["B", "C"], "consolidate": false}});
        let mut state = State::default();
        let step = tick(&mut state, &Roster, &plan, "l", START).unwrap();
        // a small army is led too (no leader bonus without a general): min_for_general is 1
        assert!(
            matches!(&step, Tick::Acted(s) if s.starts_with("command: general B -> Army 2: true")),
            "{step:?}"
        );
    }

    #[test]
    fn a_move_is_kept_against_other_steps_budgeted_and_never_made_tired() {
        let tools = fake(vec![]);
        let mut state = State::default();
        let send = |state: &mut State, at: GameHour, army: &str, to: i64, tag: &str| {
            state.clock = at;
            state
                .act(
                    &tools,
                    "l",
                    "hoi4_army_move",
                    json!({"army": army, "state_id": to}),
                    tag,
                )
                .unwrap()
        };
        assert!(send(&mut state, START, "A", 1, "hd").0);
        // another step may not override the fresh order...
        let (ok, why) = send(&mut state, START + DAY, "A", 2, "wv");
        assert!(
            !ok && why.starts_with("move_held: A is committed to its hold post move"),
            "{why}"
        );
        assert!(state.failures.is_empty(), "a held move is no failure");
        // ...but a pocket fall-back always goes, and then the hold waits for it
        assert!(send(&mut state, START + DAY, "A", 3, "wp").0);
        assert!(!send(&mut state, START + 2 * DAY, "A", 1, "hd").0);
        // the same step may update its order, within the budget (3 in 10 days)
        assert!(send(&mut state, START + 5 * DAY, "A", 1, "hd").0);
        let (ok, why) = send(&mut state, START + 6 * DAY, "A", 4, "hd");
        assert!(
            !ok && why.contains("moved 3 times in 10 game days"),
            "{why}"
        );
        // an army below its rest line moves only out of a pocket
        state.moves.tired.insert("B".into());
        assert!(!send(&mut state, START, "B", 1, "wr").0);
        assert!(send(&mut state, START, "B", 1, "wp").0);
        // the digest names each move's reason and what is held
        let d = state.moves.digest(START + 6 * DAY).unwrap();
        assert_eq!(d["A"]["moves_in_window"], 3);
        assert!(d["A"]["recent"][1]
            .as_str()
            .unwrap()
            .contains("pocket fall-back -> state 3"));
        assert!(d["A"]["held"]
            .as_str()
            .unwrap()
            .starts_with("hold post: move_held"));
    }

    #[test]
    fn a_victory_point_target_is_attacked_with_a_battle_plan_not_a_direct_move() {
        let states = json!({"states": [
            {"state_id": 1, "owner": "ITA", "controller": "ITA", "x": 0.0, "z": 0.0},
            {"state_id": 2, "owner": "ETH", "controller": "ETH", "x": 10.0, "z": 0.0,
             "provinces": [{"province": 50, "controller": "ETH"}]},
            {"state_id": 3, "owner": "ETH", "controller": "ETH", "x": 5.0, "z": 0.0}]});
        let tools = fake(vec![
            ("hoi4_states", states),
            (
                "hoi4_armies",
                json!({"armies": [{"army": "A", "division_count": 6, "main_state": 1,
                "battle_plan_orders": 0, "planning": {"mean": 0.0}}]}),
            ),
        ]);
        let plan = json!({"war": {"me": "ITA", "enemies": ["ETH"], "supply_first": false, "rest": false},
            "vp_targets": [{"province": 50, "state": 2, "army": "A"}]});
        let mut state = State {
            clock: START,
            ..Default::default()
        };
        let out = war_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(
            out.starts_with("war front and offensive A -> state 2"),
            "{out}"
        );
        let calls = tools.calls.borrow();
        assert!(!calls.iter().any(|(n, _)| n == "hoi4_army_move"));
        for line in ["hoi4_army_front", "hoi4_army_offensive"] {
            assert!(
                calls.iter().any(|(n, a)| n == line && a["state_id"] == 2),
                "{line} on the province's state"
            );
        }
        // the offensive line is drawn at the depth of the victory-point province; the front
        // order names the state alone
        assert!(calls
            .iter()
            .any(|(n, a)| n == "hoi4_army_offensive" && a["province_id"] == 50));
        assert!(calls
            .iter()
            .any(|(n, a)| n == "hoi4_army_front" && a.get("province_id").is_none()));
        drop(calls);
        // with direct moves the province itself is the order
        let mut plan = plan;
        plan["war"]["direct_moves"] = json!(true);
        let mut state = State::default();
        let out = war_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(out.starts_with("war vp target A -> province 50"), "{out}");
    }

    struct Extras(std::cell::RefCell<Vec<(String, Value)>>);
    impl Tools for Extras {
        fn call(&self, name: &str, args: &Value) -> Result<Value> {
            self.0.borrow_mut().push((name.to_string(), args.clone()));
            match name {
                "hoi4_research" => Ok(json!({"slots": [{"researching": "a"}]})),
                "hoi4_focus_completed" => Ok(json!({"active_key": "f"})),
                "hoi4_economy" => Ok(json!({"factory_trigger_count": {"military": 0},
                    "civilian_factories_available_for_projects": 0})),
                "hoi4_special_projects" => Ok(json!({
                    "facilities": [{"facility_id": 7, "project": null, "scientist": null, "specialization": "land"}],
                    "projects": [{"key": "sp_land_a", "specialization": "land", "running_in_facility_id": null},
                                 {"key": "sp_land_b", "specialization": "land", "running_in_facility_id": null},
                                 {"key": "sp_air_x", "specialization": "air", "running_in_facility_id": null}],
                    "scientists": [{"name": "Air Person", "specialization": "air", "assigned_facility_id": null, "skills": {"land": 0}},
                                   {"name": "Land Person", "specialization": "land", "assigned_facility_id": null, "skills": {"land": 2}}]})),
                "hoi4_wars" => Ok(json!({"borders": [
                    {"neighbour_tag": "DEN", "hostile": false, "own_border_states": [5]},
                    {"neighbour_tag": "POL", "hostile": true, "own_border_states": [64, 65]}]})),
                "hoi4_air" => Ok(json!({"wings": [
                    {"wing": "KG 1", "aircraft_type": "tac_bomber_equipment_1", "standing_by": true},
                    // based far from every front: out of range, never ordered
                    {"wing": "JG 9", "aircraft_type": "fighter_equipment_1", "standing_by": true,
                        "air_base": {"base_id": 1, "state_id": 2}},
                    {"wing": "JG 1", "aircraft_type": "fighter_equipment_1", "standing_by": true,
                        "air_base": {"base_id": 2, "state_id": 64}}]})),
                _ => Ok(json!({"receipt": {"status": "Verified"}})),
            }
        }
    }

