    struct War {
        liberate: bool,
        front_ok: bool,
        calls: RefCell<Vec<(String, Value)>>,
    }
    impl Tools for War {
        fn call(&self, name: &str, args: &Value) -> Result<Value> {
            self.calls
                .borrow_mut()
                .push((name.to_string(), args.clone()));
            match name {
                "hoi4_research" => Ok(json!({"slots": [{"researching": "a"}]})),
                "hoi4_focus_completed" => Ok(json!({"active_key": "f"})),
                "hoi4_economy" => Ok(json!({"factory_trigger_count": {"military": 0},
                    "civilian_factories_available_for_projects": 0})),
                "hoi4_overview" => Ok(json!({"player": "GER"})),
                "hoi4_states" => match args["query"].as_str().unwrap() {
                    "GER" => Ok(json!({"states": [
                        {"state_id": 42, "owner": "GER", "controller": "GER", "x": 0.0, "z": 0.0},
                        {"state_id": 5, "owner": "GER", "controller": if self.liberate { "POL" } else { "GER" },
                         "x": 100.0, "z": 0.0}]})),
                    "FRA" => Ok(json!({"states": [
                        {"state_id": 28, "owner": "FRA", "controller": "FRA", "x": if self.liberate { 300.0 } else { 10.0 }, "z": 10.0},
                        {"state_id": 18, "owner": "FRA", "controller": "FRA", "x": 50.0, "z": 50.0}]})),
                    "POL" => Ok(json!({"states": []})),
                    // a single state (the province count of a progress measurement): no rows
                    other if other.parse::<i32>().is_ok() => Ok(json!({"states": []})),
                    other => panic!("unexpected query {other}"),
                },
                "hoi4_armies" => Ok(json!({"unassigned_by_state": [], "armies": [
                    {"army": "Army 1", "division_count": 10, "main_state": 42,
                     "battle_plan_orders": 0, "plan_executing": false, "commander": "X"}]})),
                "hoi4_army_front" if !self.front_ok => Err(Error::new(
                    "input_readback_failed",
                    "No front line was placed",
                )),
                // the contact line as the war step reads it (no caller enemies)
                "hoi4_wars" if args.get("enemies").is_none() => {
                    let mut contact = vec![json!({"state_id": 18, "adjacent_own_states": [42]})];
                    if self.liberate {
                        contact.push(json!({"state_id": 5, "adjacent_own_states": [42]}));
                    }
                    Ok(json!({"enemy_held_adjacent_states": contact}))
                }
                _ if args.get("request_id").is_some() => {
                    Ok(json!({"receipt": {"status": "Verified"}}))
                }
                _ => Ok(json!({})),
            }
        }
    }
    /// The War fake with a validated war list (`at_war`: the countries at war) and, for
    /// single-state reads, who holds a province: (state, province, controller).
    struct Validated<'a> {
        inner: &'a War,
        at_war: Vec<&'static str>,
        holders: Vec<(i64, i64, &'static str)>,
    }
    impl Tools for Validated<'_> {
        fn call(&self, name: &str, args: &Value) -> Result<Value> {
            if name == "hoi4_wars" && args.get("enemies").is_none() {
                let mut v = self.inner.call(name, args)?;
                v["wars"] = json!({"validated": true, "enemies": self.at_war});
                return Ok(v);
            }
            if name == "hoi4_states" {
                let id = args["query"].as_str().and_then(|q| q.parse::<i64>().ok());
                let rows: Vec<Value> = self
                    .holders
                    .iter()
                    .filter(|h| Some(h.0) == id)
                    .map(|h| {
                        json!({"state_id": h.0,
                            "provinces": [{"province": h.1, "controller": h.2}]})
                    })
                    .collect();
                if !rows.is_empty() {
                    return Ok(json!({ "states": rows }));
                }
            }
            self.inner.call(name, args)
        }
    }
    fn army_orders(w: &War) -> Vec<(String, Value)> {
        w.calls
            .borrow()
            .iter()
            .filter(|(n, a)| n.starts_with("hoi4_army_") && a.get("request_id").is_some())
            .cloned()
            .collect()
    }
    fn war_plan() -> Value {
        json!({"war": {"enemies": ["FRA"], "cooldown": 40}})
    }
    fn last_action(w: &War) -> (String, Value) {
        w.calls
            .borrow()
            .iter()
            .rev()
            .find(|(n, _)| n.starts_with("hoi4_army_"))
            .cloned()
            .unwrap()
    }

