    #[test]
    fn a_failed_try_that_held_the_input_long_waits_in_proportion_from_the_first_failure() {
        struct Refuse(RefCell<usize>);
        impl Tools for Refuse {
            fn call(&self, _: &str, _: &Value) -> Result<Value> {
                *self.0.borrow_mut() += 1;
                Ok(json!({"receipt": {"status": "NotApplied"}}))
            }
        }
        let tools = Refuse(RefCell::new(0));
        let mut state = State {
            clock: START,
            wall: Some(0),
            act_seconds: Some(47),
            ..State::default()
        };
        let send = |state: &mut State, name: &str, hour: GameHour, wall: u64| -> String {
            state.clock = hour;
            state.wall = Some(wall);
            state
                .act(&tools, "l", name, json!({"state_id": 559}), "t")
                .unwrap()
                .1
        };
        // a 47 s search that ends in a refusal rests 47 * 32 game hours (about 63 days, at
        // most 60): in game time, however little wall time passed
        send(&mut state, "hoi4_army_create", START, 0);
        assert_eq!(*tools.0.borrow(), 1);
        let why = send(&mut state, "hoi4_army_create", START + 59 * DAY, 100_000);
        assert_eq!(*tools.0.borrow(), 1);
        assert!(
            why.starts_with("skipped: the last try of this order failed after 47 s on the input; it waits 1 more game days"),
            "{why}"
        );
        send(&mut state, "hoi4_army_create", START + 60 * DAY, 100_001);
        assert_eq!(*tools.0.borrow(), 2);
        // a war order that held the input 9 s rests 9 * 16 game hours (6 days) while a war runs
        state.war_active = true;
        state.act_seconds = Some(9);
        send(&mut state, "hoi4_army_move", START, 0);
        let why = send(&mut state, "hoi4_army_move", START + 5 * DAY, 0);
        assert!(why.ends_with("it waits 1 more game days"), "{why}");
        send(&mut state, "hoi4_army_move", START + 6 * DAY, 0);
        assert_eq!(*tools.0.borrow(), 4);
        // a quick refusal rests from its first failure too: not again in the same game hour
        state.act_seconds = Some(1);
        send(&mut state, "hoi4_army_assign", START, 500);
        let why = send(&mut state, "hoi4_army_assign", START, 500);
        assert!(
            why.starts_with("skipped: the same order failed 1 time(s) in a row"),
            "{why}"
        );
        assert_eq!(*tools.0.borrow(), 5);
        // while the game stands still the rest runs on wall time at speed 3's rate (8 game hours
        // a wall second)
        send(&mut state, "hoi4_army_front", START, 1_000);
        send(&mut state, "hoi4_army_front", START, 1_000);
        assert_eq!(*tools.0.borrow(), 6);
        send(&mut state, "hoi4_army_front", START, 1_001);
        assert_eq!(*tools.0.borrow(), 7);
        let why = send(&mut state, "hoi4_army_front", START, 1_001);
        assert!(
            why.starts_with("skipped: the same order failed 2 time(s)"),
            "{why}"
        );
        send(&mut state, "hoi4_army_front", START, 1_002);
        assert_eq!(
            *tools.0.borrow(),
            7,
            "the second refusal at war rests 12 game hours"
        );
        send(&mut state, "hoi4_army_front", START, 1_003);
        assert_eq!(*tools.0.borrow(), 8);
    }

    #[test]
    fn a_failing_order_backs_off_in_game_time_and_each_retry_doubles_the_wait() {
        struct Refuse(RefCell<usize>);
        impl Tools for Refuse {
            fn call(&self, _: &str, _: &Value) -> Result<Value> {
                *self.0.borrow_mut() += 1;
                Ok(json!({"receipt": {"status": "NotApplied"}}))
            }
        }
        let tools = Refuse(RefCell::new(0));
        let mut state = State {
            clock: START,
            wall: Some(0),
            ..State::default()
        };
        let send = |state: &mut State, hour: GameHour| -> String {
            state.clock = hour;
            state
                .act(
                    &tools,
                    "l",
                    "hoi4_army_create",
                    json!({"state_id": 559}),
                    "t",
                )
                .unwrap()
                .1
        };
        // the first refusal rests a game hour, the second three, the third ten game days, the
        // fourth twenty
        send(&mut state, START);
        let why = send(&mut state, START);
        assert!(
            why.starts_with("skipped: the same order failed 1 time(s) in a row"),
            "{why}"
        );
        assert_eq!(*tools.0.borrow(), 1);
        send(&mut state, START + 1);
        let why = send(&mut state, START + 3);
        assert!(why.ends_with("for 1 more game hours"), "{why}");
        send(&mut state, START + 4);
        assert_eq!(*tools.0.borrow(), 3);
        send(&mut state, START + 4 + 10 * DAY - 1);
        assert_eq!(*tools.0.borrow(), 3);
        send(&mut state, START + 4 + 10 * DAY);
        assert_eq!(*tools.0.borrow(), 4);
        send(&mut state, START + 4 + 30 * DAY - 1);
        assert_eq!(*tools.0.borrow(), 4);
        send(&mut state, START + 4 + 30 * DAY);
        assert_eq!(*tools.0.borrow(), 5);
        // the ledger survives a save of the memory beyond the old ten-day window
        let memory = state.memory(START + 40 * DAY);
        assert_eq!(
            memory["failures"]["hoi4_army_create {\"state_id\":559}"]
                .as_array()
                .map(Vec::len),
            Some(5)
        );
    }

    /// Layout fake: armies (name, state, size), the divisions hoi4_supply lists, and the actions
    /// that fail.
    struct Lay {
        calls: RefCell<Vec<(String, Value)>>,
        armies: RefCell<Value>,
        divisions: Value,
        refuse: Vec<&'static str>,
    }
    impl Tools for Lay {
        fn call(&self, name: &str, args: &Value) -> Result<Value> {
            self.calls
                .borrow_mut()
                .push((name.to_string(), args.clone()));
            if args.get("request_id").is_some() {
                if self.refuse.contains(&name) {
                    return Err(Error::new("selection_unavailable", "refused by the fake"));
                }
                if name == "hoi4_army_detach" {
                    let mut a = self.armies.borrow_mut();
                    let n = a["armies"].as_array().map_or(0, Vec::len);
                    a["armies"].as_array_mut().unwrap().push(
                        json!({"army": format!("Army {}", n + 10), "main_state": 1, "division_count": 1}),
                    );
                }
                return Ok(json!({"receipt": {"status": "Verified"}}));
            }
            Ok(match name {
                "hoi4_armies" => self.armies.borrow().clone(),
                "hoi4_supply" => json!({"divisions": self.divisions}),
                _ => json!({}),
            })
        }
    }
    impl Lay {
        fn sent(&self, tool: &str) -> usize {
            self.calls
                .borrow()
                .iter()
                .filter(|(n, a)| n == tool && a.get("request_id").is_some())
                .count()
        }
    }

    #[test]
    fn a_layout_role_that_takes_every_division_of_an_army_binds_that_army_without_a_detach() {
        // shakedown 10 Nov 2026: J_guard's detach of Army 3's only division went out 10 times
        let tools = Lay {
            calls: RefCell::new(vec![]),
            armies: RefCell::new(json!({"armies": [
                {"army": "Army 3", "main_state": 844, "division_count": 1, "commander": null}],
                "unassigned_by_state": []})),
            divisions: json!([{"army": "Army 3", "id": "d9", "template": "Fanteria"}]),
            refuse: vec![],
        };
        let plan = json!({"army_layout": [{"name_hint": "J_guard", "state": 844, "role": "guard",
            "templates": ["Fanteria"], "count": 1, "guard_states_in_order": [844]}]});
        let mut state = State::default();
        let out = layout_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(out.starts_with("layout: Army 3 is J_guard"), "{out}");
        assert_eq!(tools.sent("hoi4_army_detach"), 0);
        assert_eq!(state.layout["J_guard"], "Army 3");
        assert_eq!(state.war_guard.get("Army 3"), Some(&844));
    }

    #[test]
    fn a_layout_march_the_game_keeps_refusing_is_given_up() {
        // g17i (18 Nov 2026): Armee Nord's march to East Prussia was refused 69 times
        let tools = Lay {
            calls: RefCell::new(vec![]),
            armies: RefCell::new(json!({"armies": [
                {"army": "Army 3", "main_state": 64, "division_count": 21, "commander": null}],
                "unassigned_by_state": []})),
            divisions: json!([]),
            refuse: vec!["hoi4_army_move"],
        };
        let plan = json!({"army_layout": [
            {"name_hint": "Armee Nord", "state": 5, "role": "strike"}]});
        let mut state = State::default();
        state.layout.insert("Armee Nord".into(), "Army 3".into());
        state.done.insert("layoutformed:Armee Nord".into(), START);
        let mut outs = Vec::new();
        for day in 0..40 {
            let now = START + day * 4 * DAY;
            state.clock = now;
            if let Some(out) = layout_step(&mut state, &tools, &plan, "l", now).unwrap() {
                outs.push(out);
            }
        }
        assert!(
            outs.iter().any(|o| o.contains("march to state 5 given up")),
            "{outs:?}"
        );
        assert_eq!(
            tools.sent("hoi4_army_move"),
            LAYOUT_TRIES as usize,
            "{outs:?}"
        );
    }

    #[test]
    fn a_strike_role_with_no_army_in_its_state_is_formed_from_the_gather_army_and_marches_home() {
        // g17e/g17f: no army ever stood in East Prussia (state 5), so Armee Nord never formed
        let tools = Lay {
            calls: RefCell::new(vec![]),
            armies: RefCell::new(json!({"armies": [
                {"army": "Armee West Mitte", "main_state": 64, "division_count": 24, "commander": null}],
                "unassigned_by_state": []})),
            divisions: json!([
                {"army": "Armee West Mitte", "id": "a", "template": "Panzer-Division"},
                {"army": "Armee West Mitte", "id": "b", "template": "Infanterie-Division"},
                {"army": "Armee West Mitte", "id": "c", "template": "Infanterie-Division"},
                {"army": "Armee West Mitte", "id": "d", "template": "Infanterie-Division"}]),
            refuse: vec![],
        };
        let plan = json!({"armies": {"gather_into": "Armee West Mitte"}, "army_layout": [
            {"name_hint": "Armee Nord", "state": 5, "role": "strike",
             "templates": ["Infanterie-Division"], "count": 2},
            {"name_hint": "Armee West Mitte", "state": 64, "role": "strike"}]});
        let mut state = State::default();
        state
            .layout
            .insert("Armee West Mitte".into(), "Armee West Mitte".into());
        // it waits for an army to stand in its state first
        assert_eq!(
            layout_step(&mut state, &tools, &plan, "l", START).unwrap(),
            None
        );
        assert_eq!(tools.sent("hoi4_army_detach"), 0);
        let now = START + 31 * DAY;
        state.clock = now;
        let out = layout_step(&mut state, &tools, &plan, "l", now)
            .unwrap()
            .unwrap();
        assert!(
            out.contains("Armee Nord formed from 2 division(s) of Armee West Mitte"),
            "{out}"
        );
        let detach = tools
            .calls
            .borrow()
            .iter()
            .rev()
            .find(|(n, _)| n == "hoi4_army_detach")
            .cloned()
            .unwrap();
        assert_eq!(detach.1["divisions"], json!(["b", "c"]));
        assert_eq!(state.layout["Armee Nord"], "Army 11");
        // then it marches to its state, once
        let out = layout_step(&mut state, &tools, &plan, "l", now + 1)
            .unwrap()
            .unwrap();
        assert!(
            out.contains("Army 11 (Armee Nord) marches to its state 5: true"),
            "{out}"
        );
        let moved = tools
            .calls
            .borrow()
            .iter()
            .rev()
            .find(|(n, _)| n == "hoi4_army_move")
            .cloned()
            .unwrap();
        assert_eq!(moved.1["state_id"], json!(5));
        assert_ne!(
            layout_step(&mut state, &tools, &plan, "l", now + 2)
                .unwrap()
                .map(|s| s.contains("marches")),
            Some(true)
        );
    }

    #[test]
    fn a_state_whose_loose_divisions_cannot_form_an_army_is_given_up_and_its_roles_detach() {
        // Somaliland: two loose divisions share a province with S_strike's; army_create was
        // refused about 40 times
        let tools = Lay {
            calls: RefCell::new(vec![]),
            armies: RefCell::new(json!({"armies": [
                {"army": "S_strike", "main_state": 559, "division_count": 4, "commander": null}],
                "unassigned_by_state": [{"state_id": 559, "divisions": 2}]})),
            divisions: json!([
                {"army": "S_strike", "id": "a", "template": "Ascari Somala"},
                {"army": "S_strike", "id": "b", "template": "Banda"},
                {"army": "S_strike", "id": "c", "template": "Banda"},
                {"army": "S_strike", "id": "d", "template": "Cavalleria"}]),
            refuse: vec!["hoi4_army_create"],
        };
        let plan = json!({"army_layout": [
            {"name_hint": "S_strike", "state": 559, "role": "strike"},
            {"name_hint": "S_res", "state": 559, "role": "guard", "templates": ["Ascari Somala"],
             "count": 1, "guard_states_in_order": [559]}]});
        let mut state = State::default();
        state.layout.insert("S_strike".into(), "S_strike".into());
        for day in 0..3 {
            let now = START + day * 3 * DAY;
            state.clock = now;
            layout_step(&mut state, &tools, &plan, "l", now).unwrap();
        }
        assert_eq!(tools.sent("hoi4_army_create"), 3);
        assert!(state.done.contains_key("layout:nocreate:559"));
        let now = START + 9 * DAY;
        state.clock = now;
        let out = layout_step(&mut state, &tools, &plan, "l", now)
            .unwrap()
            .unwrap();
        assert!(out.contains("(S_res)"), "{out}");
        assert_eq!(tools.sent("hoi4_army_create"), 3, "never tried again");
        assert_eq!(tools.sent("hoi4_army_detach"), 1);
    }

    #[test]
    fn a_failing_detach_holds_back_only_its_own_role_and_is_given_up_after_three_tries() {
        struct OneRefused(Lay);
        impl Tools for OneRefused {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                if name == "hoi4_army_detach"
                    && args.get("request_id").is_some()
                    && args["divisions"] == json!(["g1"])
                {
                    self.0
                        .calls
                        .borrow_mut()
                        .push((name.to_string(), args.clone()));
                    return Ok(json!({"receipt": {"status": "NotApplied"}}));
                }
                self.0.call(name, args)
            }
        }
        let tools = OneRefused(Lay {
            calls: RefCell::new(vec![]),
            armies: RefCell::new(json!({"armies": [
                {"army": "Army 1", "main_state": 1, "division_count": 5, "commander": null}],
                "unassigned_by_state": []})),
            divisions: json!([
                {"army": "Army 1", "id": "s1", "template": "Inf"},
                {"army": "Army 1", "id": "s2", "template": "Inf"},
                {"army": "Army 1", "id": "s3", "template": "Inf"},
                {"army": "Army 1", "id": "g1", "template": "G1"},
                {"army": "Army 1", "id": "g2", "template": "G2"}]),
            refuse: vec![],
        });
        let plan = json!({"army_layout": [
            {"name_hint": "Strike", "state": 1, "role": "strike"},
            {"name_hint": "G1", "state": 1, "role": "guard", "templates": ["G1"], "count": 1},
            {"name_hint": "G2", "state": 1, "role": "guard", "templates": ["G2"], "count": 1}]});
        let mut state = State::default();
        layout_step(&mut state, &tools, &plan, "l", START).unwrap();
        let out = layout_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(out.contains("detach for G1 from Army 1: false"), "{out}");
        // the same game hour: G2 is not held back by G1's failure
        let out = layout_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(out.contains("(G2)"), "{out}");
        for day in 1..=2 {
            let now = START + day * 3 * DAY;
            state.clock = now;
            state.wall = Some(day as u64 * 10_000);
            layout_step(&mut state, &tools, &plan, "l", now).unwrap();
        }
        assert!(state.done.contains_key("layout:impossible:G1"));
        assert_eq!(state.layout.get("G1").map(String::as_str), Some(""));
    }

    /// The War fake with other armies.
    struct WarArmies(War, Value);
    impl Tools for WarArmies {
        fn call(&self, name: &str, args: &Value) -> Result<Value> {
            if name == "hoi4_armies" {
                self.0
                    .calls
                    .borrow_mut()
                    .push((name.to_string(), args.clone()));
                return Ok(self.1.clone());
            }
            if name == "hoi4_army_create" && args.get("request_id").is_some() {
                self.0
                    .calls
                    .borrow_mut()
                    .push((name.to_string(), args.clone()));
                return Err(Error::new("selection_unavailable", "refused by the fake"));
            }
            self.0.call(name, args)
        }
    }
    fn war(liberate: bool) -> War {
        War {
            liberate,
            front_ok: true,
            calls: RefCell::new(vec![]),
        }
    }

