    #[test]
    fn an_empty_axes_list_is_a_hold_phase_without_any_attack() {
        let w = war(false);
        let mut state = State::default();
        let plan = json!({"war": {"enemies": ["FRA"], "axes": []}});
        let orders = |w: &War| -> Vec<String> {
            w.calls
                .borrow()
                .iter()
                .filter(|(n, a)| n.starts_with("hoi4_army_") && a.get("request_id").is_some())
                .map(|(n, _)| n.clone())
                .collect()
        };
        // an army with no target of its own (no layout axis, no victory-point row) gets no order
        tick(&mut state, &w, &plan, "l", START).unwrap();
        assert!(orders(&w).is_empty(), "{:?}", w.calls.borrow());
        // with a victory-point row the hold prepares: the army draws its front and its offensive
        // line on the row's state and plans there, and no execute order follows in the hold
        let mut prepared = plan.clone();
        prepared["vp_targets"] = json!([{"province": 280, "state": 28, "army": "Army 1"}]);
        let w = war(false);
        let mut state = State::default();
        let step = tick(&mut state, &w, &prepared, "l", START).unwrap();
        assert_eq!(
            step,
            Tick::Acted("war front and offensive Army 1 -> state 28: ok".into())
        );
        for day in 1..=20 {
            assert_eq!(
                tick(&mut state, &w, &prepared, "l", START + day * DAY).unwrap(),
                Tick::Nothing,
                "day {day}"
            );
        }
        assert_eq!(orders(&w), ["hoi4_army_front", "hoi4_army_offensive"]);
        // "hold_prepares": false keeps the old hold: no line on enemy land at all
        prepared["war"]["hold_prepares"] = json!(false);
        let w = war(false);
        let mut state = State::default();
        for day in 0..3 {
            assert_eq!(
                tick(&mut state, &w, &prepared, "l", START + day * DAY).unwrap(),
                Tick::Nothing
            );
        }
        assert!(orders(&w).is_empty(), "{:?}", w.calls.borrow());
        // an own state to retake is still retaken (held whole by the enemy: with a battle plan)
        let w = war(true);
        let mut state = State::default();
        let step = tick(&mut state, &w, &plan, "l", START).unwrap();
        assert!(
            matches!(&step, Tick::Acted(s) if s.starts_with("war front and offensive Army 1 -> state 5")),
            "{step:?}"
        );
        // a defender's hold retakes nothing and prepares nothing on enemy land: its armies only
        // hold with a front line where they stand
        let mut defend = prepared.clone();
        defend["war"] = json!({"enemies": ["FRA"], "axes": [], "posture": "defend"});
        for liberate in [false, true] {
            let w = war(liberate);
            let mut state = State::default();
            for day in 0..3 {
                tick(&mut state, &w, &defend, "l", START + day * DAY).unwrap();
            }
            let sent = orders(&w);
            assert!(
                !sent.is_empty() && sent.iter().all(|n| n == "hoi4_army_front"),
                "liberate {liberate}: {sent:?}"
            );
        }
    }

    #[test]
    fn a_pocket_fall_back_stays_within_reach_and_within_the_layout_roles_states() {
        let encircled = |state: i64| {
            json!({"unassigned_by_state": [], "armies": [
                {"army": "Army 1", "division_count": 10, "main_state": state,
                 "battle_plan_orders": 0, "plan_executing": false, "commander": "X",
                 "threat": {"share": 0.8, "encirclement_risk": true}}]})
        };
        // an army_layout role falls back only into its own states
        let w = WarArmies(war(false), encircled(42));
        let mut state = State::default();
        state.layout.insert("Guard".into(), "Army 1".into());
        state.clock = START;
        let plan = json!({"war": {"enemies": ["FRA"]},
            "army_layout": [{"name_hint": "Guard", "state": 42, "role": "guard",
                "guard_states_in_order": [42]}]});
        let step = war_step(&mut state, &w, &plan, "l", START).unwrap();
        assert!(
            !step.as_deref().is_some_and(|s| s.starts_with("war pocket")),
            "{step:?}"
        );
        // without the role the neighbour 100 map units away is in reach
        let mut state = State::default();
        let step = tick(&mut state, &w, &war_plan(), "l", START).unwrap();
        assert!(
            matches!(&step, Tick::Acted(s) if s.starts_with("war pocket Army 1")),
            "{step:?}"
        );
        // in enemy land, but every fully held own state lies beyond pocket_reach
        let w = WarArmies(war(false), encircled(28));
        let mut state = State::default();
        let plan = json!({"war": {"enemies": ["FRA"], "pocket_reach": 5.0}});
        let step = tick(&mut state, &w, &plan, "l", START).unwrap();
        assert!(
            !matches!(&step, Tick::Acted(s) if s.starts_with("war pocket")),
            "{step:?}"
        );
    }

    #[test]
    fn an_army_with_a_front_from_before_a_restart_goes_on_to_the_offensive() {
        let w = WarArmies(
            war(false),
            json!({"unassigned_by_state": [], "armies": [
                {"army": "Army 1", "division_count": 10, "main_state": 42,
                 "battle_plan_orders": 1, "plan_executing": false, "commander": "X",
                 "planning": {"mean": 0.44}}]}),
        );
        let mut before = State::default();
        before.war_stage.insert("Army 1".into(), 1);
        before.war_assign.insert("Army 1".into(), 28);
        let saved = before.memory(START);
        let mut state = State::default();
        state.restore(&saved, START);
        let step = tick(&mut state, &w, &war_plan(), "l", START).unwrap();
        assert!(
            matches!(&step, Tick::Acted(s) if s.starts_with("war offensive Army 1")),
            "{step:?}"
        );
        assert!(!w
            .0
            .calls
            .borrow()
            .iter()
            .any(|(n, _)| n == "hoi4_army_front"));
    }

