    #[test]
    fn dates_map_to_raw_game_hours() {
        // 1936.01.01.12 read live as 60759371 (hour 11 of the day, counted from 0)
        assert_eq!(super::date_hour("1936.01.01"), Some(60759360));
        assert_eq!(
            super::date_hour("1936-03-05"),
            Some(60759360 + (31 + 28 + 4) * 24)
        );
        assert_eq!(super::date_hour("1936.13.01"), None);
        assert_eq!(super::game_year(60759371), Some(1936));
    }

    /// t1939l/t1939m: one plan item per air base level in a state went out one level at a time,
    /// the same order to the same state twice within days; the levels now go in one order.
    #[test]
    fn plan_items_of_one_building_in_one_state_go_in_one_order() {
        let items = vec![
            json!({"id": "ab_42_1", "building": "air_base", "state": 42, "when": "1938.3.1"}),
            json!({"id": "ab_42_2", "building": "air_base", "state": 42, "when": "1938.3.1"}),
            json!({"id": "ab_42_3", "building": "air_base", "state": 42, "when": "1938.3.1"}),
            json!({"id": "ab_51_1", "building": "air_base", "state": 51, "when": "1938.3.1"}),
            json!({"id": "ab_42_p", "building": "air_base", "state": 42, "province": 9, "when": "1938.3.1"}),
            json!({"id": "rd_42", "building": "radar_station", "state": 42, "when": "1938.3.1"}),
            json!({"id": "ab_42_late", "building": "air_base", "state": 42, "when": "1940.1.1"}),
        ];
        let key_of = |i: &Value| format!("id:{}", i["id"].as_str().unwrap());
        let all = super::same_order_siblings(&items, &items[0], &key_of, |_| true);
        assert_eq!(all, vec!["id:ab_42_2", "id:ab_42_3"]);
        // a level already queued is not sent again
        let rest = super::same_order_siblings(&items, &items[0], &key_of, |k| k != "id:ab_42_2");
        assert_eq!(rest, vec!["id:ab_42_3"]);
        // an item with its own province goes alone
        assert!(super::same_order_siblings(&items, &items[4], &key_of, |_| true).is_empty());
        assert!(super::same_order_siblings(&items, &items[3], &key_of, |_| true).is_empty());
    }

    #[test]
    fn construction_plan_items_wait_for_their_trigger_and_go_once() {
        struct Plan(RefCell<Vec<(String, Value)>>, RefCell<&'static str>);
        impl Tools for Plan {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                self.0.borrow_mut().push((name.to_string(), args.clone()));
                Ok(match name {
                    "hoi4_overview" => json!({"player": "ITA"}),
                    "hoi4_states" => json!({"states": [{"state_id": 842, "owner": "ETH",
                        "provinces": [{"province": 13238, "controller": *self.1.borrow()},
                                      {"province": 2072, "controller": "ETH"}]}]}),
                    _ if args.get("request_id").is_some() => {
                        json!({"receipt": {"status": "Verified"}})
                    }
                    _ => json!({}),
                })
            }
        }
        let plan = json!({"construction_plan": [
            {"order": 3, "building": "rail_way", "from_state": 550, "to_state": 842,
             "path": [13250, 13238], "when": "province_controlled:13238"},
            {"order": 5, "building": "supply_node", "state": 842, "province": 2072,
             "when": "state_fully_controlled:842"}]});
        let tools = Plan(RefCell::new(vec![]), RefCell::new("ETH"));
        let mut state = State::default();
        let built = |t: &Plan| {
            t.0.borrow()
                .iter()
                .filter(|(n, _)| n == "hoi4_railway_build" || n == "hoi4_construction_add")
                .count()
        };
        assert_eq!(
            construction_plan_step(&mut state, &tools, &plan, "l", START).unwrap(),
            None
        );
        *tools.1.borrow_mut() = "ITA";
        let step = construction_plan_step(&mut state, &tools, &plan, "l", START).unwrap();
        assert!(step.unwrap().starts_with("construction plan #3"));
        let rail = tools
            .0
            .borrow()
            .iter()
            .find(|(n, _)| n == "hoi4_railway_build")
            .cloned()
            .unwrap();
        assert_eq!(rail.1["from_province"], 13250);
        assert_eq!(rail.1["to_province"], 13238);
        // #3 done, #5 waits for all of 842
        assert_eq!(
            construction_plan_step(&mut state, &tools, &plan, "l", START).unwrap(),
            None
        );
        assert_eq!(built(&tools), 1);
        assert_eq!(rail.1["from_nearest_node"], true);
    }

    #[test]
    fn a_railway_across_land_not_held_yet_waits_without_spending_its_tries() {
        struct Cut(RefCell<u32>);
        impl Tools for Cut {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                Ok(match name {
                    "hoi4_overview" => json!({"player": "ITA"}),
                    "hoi4_railway_build" => {
                        *self.0.borrow_mut() += 1;
                        return Err(Error::new(
                            "route_not_controlled",
                            "Own-controlled land does not join start 13250 and target 1984",
                        ));
                    }
                    _ if args.get("request_id").is_some() => {
                        json!({"receipt": {"status": "Verified"}})
                    }
                    _ => json!({}),
                })
            }
        }
        let plan = json!({"construction_plan": [{"id": "r1", "building": "rail_way",
            "from_state": 550, "to_state": 841, "path": [13250, 1984], "when": ""}]});
        let tools = Cut(RefCell::new(0));
        let mut state = State::default();
        let mut now = START;
        for _ in 0..6 {
            construction_plan_step(&mut state, &tools, &plan, "l", now).unwrap();
            now += 3 * DAY;
        }
        // tried each time it came round (no ledger give-up), never blocked, no tries spent
        assert_eq!(*tools.0.borrow(), 6);
        assert!(state.plan_blocked.is_empty() && state.plan_tries.is_empty());
        assert!(state.failed_run.is_empty() && state.gave_up.is_empty());
    }

    #[test]
    fn a_railway_item_sends_only_the_ends_it_names_and_one_without_a_target_is_reported() {
        let tools = fake(vec![("hoi4_overview", json!({"player": "ETH"}))]);
        let plan = json!({"construction_plan": [
            {"id": "to", "building": "rail_way", "to_state": 841, "when": ""},
            {"id": "none", "building": "rail_way", "when": ""}]});
        let mut state = State::default();
        construction_plan_step(&mut state, &tools, &plan, "l", START).unwrap();
        let sent: Vec<Value> = actions(&tools)
            .into_iter()
            .filter(|(n, _)| n == "hoi4_railway_build")
            .map(|(_, a)| a)
            .collect();
        assert_eq!(sent.len(), 1);
        assert_eq!(sent[0]["to_state"], 841);
        assert!(sent[0].get("from_state").is_none(), "{}", sent[0]);
        assert_eq!(sent[0]["from_nearest_node"], true);
        // the item with no target is never sent: reported once, at once
        let out = construction_plan_step(&mut state, &tools, &plan, "l", START + 3 * DAY)
            .unwrap()
            .unwrap();
        assert!(out.contains("names no target"), "{out}");
        assert!(state.plan_blocked.contains_key("id:none"));
        assert_eq!(
            actions(&tools)
                .iter()
                .filter(|(n, _)| n == "hoi4_railway_build")
                .count(),
            1
        );
    }

    #[test]
    fn a_railway_item_with_legs_is_sent_again_leg_by_leg_until_the_railway_is_complete() {
        // answers in turn: a leg laid, the own part already laid (a wait), the whole way laid
        struct Legs(RefCell<Vec<Value>>);
        impl Tools for Legs {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                Ok(match name {
                    "hoi4_overview" => json!({"player": "GER"}),
                    "hoi4_railway_build" => {
                        self.0.borrow_mut().push(args.clone());
                        match self.0.borrow().len() {
                            1 => json!({"receipt": {"status": "Verified"}}),
                            2 => return Err(Error::new("leg_built", "waits for more land")),
                            _ => return Err(Error::new("railway_complete", "stands")),
                        }
                    }
                    _ if args.get("request_id").is_some() => {
                        json!({"receipt": {"status": "Verified"}})
                    }
                    _ => json!({}),
                })
            }
        }
        let plan = json!({"construction_plan": [{"id": "east", "building": "rail_way",
            "from_state": 10, "to_state": 219, "legs": true, "leg_days": 7, "when": ""}]});
        let tools = Legs(RefCell::new(Vec::new()));
        let mut state = State::default();
        let mut now = START;
        for _ in 0..8 {
            construction_plan_step(&mut state, &tools, &plan, "l", now).unwrap();
            state.failures.clear();
            now += 4 * DAY;
        }
        let sent = tools.0.borrow();
        assert_eq!(sent.len(), 3, "one leg a week, never between: {sent:?}");
        assert_eq!(sent[0]["leg"], true);
        assert_eq!(
            (sent[0]["from_state"].clone(), sent[0]["to_state"].clone()),
            (json!(10), json!(219))
        );
        assert!(state.plan_built.contains_key("id:east"));
        assert!(state.plan_tries.is_empty() && state.plan_blocked.is_empty());
    }

    #[test]
    fn a_construction_plan_item_waits_for_the_technology_it_requires_without_spending_tries() {
        // g17n, g17o, s53a: radar_station was dated 1940.3.1, the radar project that grants
        // radio_detection still ran in May 1940; three refusals per state gave the items up.
        struct Radar(RefCell<Vec<String>>, RefCell<u32>);
        impl Tools for Radar {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                Ok(match name {
                    "hoi4_overview" => json!({"player": "GER"}),
                    "hoi4_research" => json!({"researched": self.0.borrow().clone()}),
                    "hoi4_construction_add" => {
                        *self.1.borrow_mut() += 1;
                        json!({"receipt": {"status": "Verified"}})
                    }
                    _ if args.get("request_id").is_some() => {
                        json!({"receipt": {"status": "Verified"}})
                    }
                    _ => json!({}),
                })
            }
        }
        let plan = json!({"construction_plan": [{"id": "radar_56", "building": "radar_station",
            "state": 56, "when": "", "requires": "radio_detection"}]});
        let tools = Radar(RefCell::new(vec!["radio".into()]), RefCell::new(0));
        let mut state = State::default();
        let mut now = START;
        for _ in 0..6 {
            assert_eq!(
                construction_plan_step(&mut state, &tools, &plan, "l", now).unwrap(),
                None
            );
            now += 8 * DAY;
        }
        assert_eq!(*tools.1.borrow(), 0);
        assert!(state.plan_tries.is_empty() && state.plan_blocked.is_empty());
        let note = manage_note(&state, "construction_plan");
        assert!(
            note.contains("waits for radio_detection"),
            "{note:?} {:?}",
            state.plan_waits
        );
        tools.0.borrow_mut().push("radio_detection".into());
        let step = construction_plan_step(&mut state, &tools, &plan, "l", now).unwrap();
        assert!(step.unwrap().contains("radar_station in 56: true"));
        assert_eq!(*tools.1.borrow(), 1);
        assert!(state.plan_waits.is_empty());
    }

