    #[test]
    fn every_army_without_an_order_gets_a_hold_while_operations_carry_the_war() {
        let board = Board::new(vec![
            ("Army 1", 42, vec![("a", "Inf", 42)]),
            ("Armee Mitte", 66, vec![("m", "Inf", 66)]),
        ]);
        let plan = json!({"war": {"land_orders": false},
            "operations": [{"id": "op", "prepare_from": "date >= 1939.7.15", "formations": [
                {"army": "Armee Mitte", "role": "line"}]}]});
        let mut state = State::default();
        state.op_owned.insert("Armee Mitte".into(), "op".into());
        let mut roster = board.call("hoi4_armies", &json!({})).unwrap();
        let active = vec![("op".to_string(), plan["operations"][0].clone())];
        let now = hour("1939.08.20");
        // an army without a general takes no battle-plan order: it waits for the command step
        for a in roster["armies"].as_array_mut().unwrap() {
            a["commander"] = Value::Null;
        }
        assert_eq!(
            plan_operation::idle_holds(
                &mut state,
                &board,
                &plan,
                &active,
                &roster,
                &json!({}),
                "l",
                now
            )
            .unwrap(),
            None
        );
        for a in roster["armies"].as_array_mut().unwrap() {
            a["commander"] = json!("Erwin Rommel");
        }
        let line = plan_operation::idle_holds(
            &mut state,
            &board,
            &plan,
            &active,
            &roster,
            &json!({}),
            "l",
            now,
        )
        .unwrap()
        .unwrap();
        assert!(
            line.contains("Army 1 has no order: it holds [42]"),
            "{line}"
        );
        // the owned army is the operation's; the held one is not ordered twice
        let roster = board.call("hoi4_armies", &json!({})).unwrap();
        assert_eq!(
            plan_operation::idle_holds(
                &mut state,
                &board,
                &plan,
                &active,
                &roster,
                &json!({}),
                "l",
                now + 2 * DAY
            )
            .unwrap(),
            None
        );
        // land orders on: the war step orders every army itself
        let on = json!({"operations": plan["operations"].clone()});
        let mut fresh = State::default();
        assert_eq!(
            plan_operation::idle_holds(
                &mut fresh,
                &board,
                &on,
                &active,
                &roster,
                &json!({}),
                "l",
                now
            )
            .unwrap(),
            None
        );
    }

    #[test]
    fn army_layout_takes_the_strike_army_and_detaches_a_guard_by_template() {
        struct L(RefCell<Vec<(String, Value)>>, RefCell<bool>);
        impl Tools for L {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                self.0.borrow_mut().push((name.to_string(), args.clone()));
                let split = *self.1.borrow();
                Ok(match name {
                    "hoi4_armies" => {
                        let mut a =
                            vec![json!({"army": "Army 1", "main_state": 550, "commander": null})];
                        if split {
                            a.push(json!({"army": "Army 2", "main_state": 550, "commander": null}));
                        }
                        json!({"armies": a})
                    }
                    "hoi4_supply" => json!({"divisions": [
                        {"army": "Army 1", "id": "d1", "template": "Divisione di Fanteria"},
                        {"army": "Army 1", "id": "d2", "template": "Camicie Nere"},
                        {"army": "Army 1", "id": "d3", "template": "Camicie Nere"},
                        {"army": "Army 1", "id": "d4", "template": "Camicie Nere"}]}),
                    "hoi4_army_detach" => {
                        *self.1.borrow_mut() = true;
                        json!({"receipt": {"status": "Verified"}})
                    }
                    _ if args.get("request_id").is_some() => {
                        json!({"receipt": {"status": "Verified"}})
                    }
                    _ => json!({}),
                })
            }
        }
        let plan = json!({"army_layout": [
            {"name_hint": "North strike (Army 1)", "state": 550, "role": "strike", "general": "Giovanni Messe"},
            {"name_hint": "North guard", "state": 550, "role": "guard", "templates": ["Camicie Nere"],
             "count": 2, "guard_states_in_order": [550]}]});
        let tools = L(RefCell::new(vec![]), RefCell::new(false));
        let mut state = State::default();
        let s1 = layout_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert_eq!(s1, "layout: Army 1 is North strike (Army 1)");
        let s2 = layout_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(s2.contains("-> Army 2 (North guard)"), "{s2}");
        let detach = tools
            .0
            .borrow()
            .iter()
            .find(|(n, _)| n == "hoi4_army_detach")
            .cloned()
            .unwrap();
        assert_eq!(detach.1["divisions"], json!(["d2", "d3"]));
        assert_eq!(state.war_guard.get("Army 2"), Some(&550));
        let s3 = layout_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(
            s3.starts_with("layout general Giovanni Messe -> Army 1"),
            "{s3}"
        );
        assert_eq!(
            layout_step(&mut state, &tools, &plan, "l", START).unwrap(),
            None
        );
    }

    #[test]
    fn army_layout_carves_an_operation_army_out_of_an_army_that_operation_owns() {
        struct L(RefCell<Vec<(String, Value)>>, RefCell<bool>);
        impl Tools for L {
            fn call(&self, name: &str, args: &Value) -> Result<Value> {
                self.0.borrow_mut().push((name.to_string(), args.clone()));
                let split = *self.1.borrow();
                Ok(match name {
                    "hoi4_armies" => {
                        let mut a =
                            vec![json!({"army": "Army 1", "main_state": 550, "commander": null})];
                        if split {
                            a.push(json!({"army": "Army 2", "main_state": 550, "commander": null}));
                        }
                        json!({"armies": a})
                    }
                    "hoi4_supply" => json!({"divisions": [
                        {"army": "Army 1", "id": "d1", "template": "Divisione di Fanteria"},
                        {"army": "Army 1", "id": "d2", "template": "Camicie Nere"},
                        {"army": "Army 1", "id": "d3", "template": "Camicie Nere"}]}),
                    "hoi4_army_detach" => {
                        *self.1.borrow_mut() = true;
                        json!({"receipt": {"status": "Verified"}})
                    }
                    _ => json!({}),
                })
            }
        }
        let layout = json!([
            {"name_hint": "North Strike", "state": 550, "role": "strike"},
            {"name_hint": "North Guard", "state": 550, "role": "guard", "templates": ["Camicie Nere"],
             "count": 2, "guard_states_in_order": [550]}]);
        // the operation names North Guard: the detach out of its owned North Strike goes out
        let plan = json!({"army_layout": layout, "operations": [{"id": "op", "formations": [
            {"army": "North Strike", "role": "mobile"}],
            "holds": [{"armies": [{"army": "North Guard"}], "states": [550]}]}]});
        let tools = L(RefCell::new(vec![]), RefCell::new(false));
        let mut state = State::default();
        layout_step(&mut state, &tools, &plan, "l", START).unwrap();
        state.op_owned.insert("Army 1".into(), "op".into());
        let s2 = layout_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(s2.contains("-> Army 2 (North Guard)"), "{s2}");
        assert!(!state.op_acting);
        // a role no operation names is still refused out of an owned army
        let plan = json!({"army_layout": layout, "operations": [{"id": "op", "formations": [
            {"army": "North Strike", "role": "mobile"}]}]});
        let tools = L(RefCell::new(vec![]), RefCell::new(false));
        let mut state = State::default();
        layout_step(&mut state, &tools, &plan, "l", START).unwrap();
        state.op_owned.insert("Army 1".into(), "op".into());
        let s2 = layout_step(&mut state, &tools, &plan, "l", START)
            .unwrap()
            .unwrap();
        assert!(s2.contains("owned_by_operation"), "{s2}");
    }

