    struct WithWatcher<'a>(&'a Fake, Value);
    impl Tools for WithWatcher<'_> {
        fn call(&self, name: &str, args: &Value) -> Result<Value> {
            if name == "hoi4_date_stop" {
                return Ok(self.1.clone());
            }
            self.0.call(name, args)
        }
    }

